public void addMessage(final LogRecord lr) {
	// Create a request to add the log record to the LogTable
	SwingUtilities.invokeLater(new Runnable() {
		@Override
		public void run() {
			// Get the LogTable component and its model
			LogTable logTable = (LogTable) SwingUtilities.getRoot(getParent()).getComponentByName("logTable");
			LogTableModel model = (LogTableModel) logTable.getModel();

			// Add the log record to the model
			model.addRecord(lr);

			// Make sure the log table is visible and has focus
			logTable.setVisible(true);
			logTable.requestFocus();
		}
	});
}

