public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep == 1) {
        return timeBucket;
    }
    long days = timeBucket / 10000;
    long month = timeBucket % 1000;
    long year = timeBucket / 1000000;
    month = month + dayStep;
    while (month > 12) {
        month = month - 12;
        year++;
    }
    return year * 1000000 + month * 1000 + days;
}
