public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Get the path from the URI
    String path = u.getPath();

    // Split the path into segments
    String[] segments = path.split("/");

    // Create a new list to store the decoded path segments
    List<PathSegmentImpl> decodedPath = new ArrayList<>();

    // Loop through the segments and decode them
    for (int i = 0; i < segments.length; i++) {
        String segment = segments[i];
        // Decode the segment if necessary
        if (decode) {
            try {
                segment = URLDecoder.decode(segment, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                // Ignore and skip this segment
                continue;
            }
        }

        // Create a new PathSegmentImpl object and add it to the list
        decodedPath.add(new PathSegmentImpl(segment, i != segments.length - 1));
    }

    return decodedPath;
}
