private static boolean isPrime(int number) {
    // Check if the number is less than or equal to 1
    if (number <= 1) {
        return false;
    }

    // Check if the number is divisible by 2 to 10
    for (int i = 2; i <= 10; i++) {
        if (number % i == 0) {
            return false;
        }
    }

    return true;
