public static int nextPrime(int desiredCapacity) {
  if (desiredCapacity < 0) {
    throw new IllegalArgumentException("Invalid desired capacity: " + desiredCapacity);
  }

  if (desiredCapacity == 0) {
    return 1;
  }

  if (desiredCapacity == 1) {
    return 2;
  }

  int result = desiredCapacity - 1;

  if (result < 2) {
    return 2;
  }

  if (result < 4) {
    if (result == 2) {
      return 3;
    }
    return 2;
  }

  if (result % 2 == 0) {
    result--;
  }

  for (int i = 3; i * i <= result; i += 2) {
    if (result % i == 0) {
      while (result % i == 0) {
        result /= i;
      }
      i = 1;
    }
  }

  return result;
}
