        return str;
    }
    java.util.regex.Matcher matcher = java.util.regex.Pattern.compile("\\\\[\\\\nN\bB\fR\t]").matcher(str);
    java.lang.StringBuffer buffer = new java.lang.StringBuffer();
    while (matcher.find()) {
        String sequence = matcher.group();
        switch (sequence.charAt(1)) {
            case 'n':
                matcher.appendReplacement(buffer, "\n");
                break;
            case 'N':
                matcher.appendReplacement(buffer, "\n");
                break;
            case 'B':
                matcher.appendReplacement(buffer, "\b");
                break;
            case 'R':
                matcher.appendReplacement(buffer, "\r");
                break;
            case 't':
                matcher.appendReplacement(buffer, "\t");
                break;
            default:
                matcher.appendReplacement(buffer, "\\" + sequence.charAt(1));
                break;
        }
    }
    matcher.appendTail(buffer);
    return buffer.toString();
