public static byte convertHexDigit(byte b) {
	// Check if the input is a valid hex digit
	if (!((b >= 48 && b <= 57) || (b >= 65 && b <= 70) || (b >= 97 && b <= 102))) {
		throw new IllegalArgumentException("Invalid hex digit: " + (char) b);
	}

	// Compute the value of the hex digit
	byte value = (byte) (b - 48); // 0-9
	if (b >= 65) { // A-F
		value += 9;
	} else if (b >= 97) { // a-f
		value += 39;
	}

	return value;
}

