 * @param bucketsByLabel the buckets vertices are stored in
 * @param labels the labels of the vertices
 * @param minLabel the minimum value of the non-empty bucket
 */
private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            bucketsByLabel.get(0).addAll(bucketsByLabel.get(minLabel));
            bucketsByLabel.get(minLabel).clear();
        }
    }

    // Update the labeling accordingly
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) > minLabel) {
            labels.set(i, labels.get(i) - 1);
        }
    }
