            Set<V> neighbors = graph.neighborSetOf(vertex);

            // Compute the minimal separators of vertex
            List<Pair<Integer,Integer>> minimalSeparators = new ArrayList<>();

            // Iterate over the neighbors and construct the minimal separators
            for (V neighbor : neighbors) {
