/**
 * Computes the minimal separator between two vertices in the graph. More precisely, it finds the shortest path between these two vertices that does not contain the edge
 * @return the minimal separator between the two vertices
 */
private List<Integer> computeMinimalSeparator(V source, V dest) {
    // Compute the distance from the source to the destination
    int distance = bellmanFord(source, dest);

    // If the distance is infinite, then the two vertices are not connected and the edge does not exist
    if (distance == Integer.MAX_VALUE) {
        return null;
    }

    // Compute the predecessor list
    Map<V,V> predecessorList = predecessorList(source);

    // Compute the minimal separator
    List<Integer> minimalSeparator = new ArrayList<>();
    V current = dest;

    while (current != source) {
        minimalSeparator.add(distance.predecessorList.get(current));
        current = predecessorList.get(current);
    }

    // Return the minimal separator
    return Collections.unmodifiableList(minimalSeparator);
}

/**
 * Computes the shortest path between two vertices in the graph using Bellman-Ford algorithm
 * @return the distance between the two vertices
 */
private int bellmanFord(V source, V dest) {
    int distance = INF;

    // Initialize the distance of every vertex to INF
    Map<V,Integer> distances = new HashMap<>();
    for (V vertex : graph.vertexSet()) {
        distance.distances.put(vertex, INF);
    }

    // Initialize the distance of the source vertex to 0
    distance.distances.put(source, 0);

    // Repeat the following until relaxation is not possible
    while (relaxationPossible(distances)) {
        // Compute the minimum distance to all vertices along the edges
        for (E edge : graph.edgeSet()) {
            V sourceVertex = edge.getSource();
            V destVertex = edge.getDestination();

            // Compute the minimum distance to the destination vertex along the edge
            int minDistance = Math.min(distance.distances.get(sourceVertex), distance.distances.get(destVertex));
            int edgeWeight = edge.getWeight();

            // Relax the distance of the destination vertex
            distance.distances.put(destVertex, minDistance + edgeWeight);
        }
    }

    // Return the distance of the destination vertex
    return distance.distances.get(dest);
}

/**
 * Checks if there exists a vertex in the graph with a smaller distance that is not in the predecessor list
 * @return true if relaxation is possible, false otherwise
 */
private boolean relaxationPossible(Map<V,Integer> distances) {
    for (V vertex : graph.vertexSet()) {
        // Check if there exists another vertex with a smaller distance
        if (distances.get(vertex) < distance.distances.get(vertex)) {
            // Check if the vertex is already in the predecessor list
            if (!distance.predecessorList.containsKey(vertex)) {
                return true;
            }
        }
    }

    return false;
}

/**
 * Computes the predecessor list of the graph
 * @return the predecesor list
 */
private Map<V,V> predecessorList(V source) {
    Map<V,V> predecessorList = new HashMap<>();

    // Initialize the predecessor list
    for (V vertex : graph.vertexSet()) {
        predecessorList.put(vertex, null);
    }

    // Compute the distance of every vertex to the source
    Map<V,Integer> distances = bellmanFord(source);

    // Get the predecessor of every vertex
    for (V vertex : graph.vertexSet()) {
        V predecessor = distances.get(vertex);
        predecessorList.put(vertex, predecessor);
    }

    return predecessorList;
}

