```
public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
  // Check if the file is valid
  if (!file.exists() || !file.isFile() || !file.canRead()) {
    throw new IOException("File not found or is not a valid file");
  }

  // Open the file for reading
  RandomAccessFile raf = new RandomAccessFile(file, "r");

  // Create a new list to store the thread snapshots
  List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

  // Loop through the time ranges
  for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
    // Calculate the start and end indexes of the time range
    long startIndex = (long) (timeRange.getStartTime() * ThreadSnapshot.TIME_INDEX_MAX);
    long endIndex = (long) (timeRange.getEndTime() * ThreadSnapshot.TIME_INDEX_MAX);

    // Read the data from the file
    long filePointer = 0L;
    while (filePointer < raf.length()) {
      // Read the thread id and timestamp
      int threadId = raf.readInt();
      long timestamp = raf.readLong();

      // Check if the thread id and timestamp are within the time range
      if (threadId >= startIndex && threadId <= endIndex && timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
        // Read the thread snapshot data
        ThreadSnapshot snapshot = new ThreadSnapshot(threadId);
        snapshot.setTimestamp(timestamp);
        snapshot.setSuspended(raf.readBoolean());
        snapshot.setRunnable(raf.readBoolean());
        snapshot.setBlocked(raf.readBoolean());
        snapshot.setBlockedReason(raf.readUTF());
        snapshot.setRunning(raf.readBoolean());
        snapshot.setBuildable(raf.readBoolean());
        snapshot.setMonitor(raf.readUTF());
        snapshot.setLock(raf.readUTF());
        snapshot.setObject(raf.readUTF());
        snapshot.setStack(raf.readUTF());
        snapshot.setID(threadId);

        // Add the thread snapshot to the list
        threadSnapshots.add(snapshot);
      }

      // Move to the next timestamp
      filePointer += ThreadSnapshot.HEADER_SIZE;
    }
  }

  // Close the file
